package com.kairos.learn

import android.content.Context
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import org.json.JSONArray
import org.json.JSONObject

/**
 * The Learn course, read from `assets/learn/deer.json`. That file is generated by
 * tools/build_learn_asset.py from the lesson files in notes/learn (which stay out of the
 * public repo), so edit the lessons there and re-run the tool rather than editing the JSON.
 */
data class Course(
    val units: List<LearnUnit>,
    val entries: Map<String, Entry>,
    val videos: Map<String, Video>,
) {
    val lessons: List<Lesson> get() = units.flatMap { it.lessons }
    fun lesson(id: String): Lesson? = lessons.firstOrNull { it.id == id }
    fun unitOf(lessonId: String): LearnUnit? = units.firstOrNull { u -> u.lessons.any { it.id == lessonId } }

    /** Every video the lesson's sections cite, in first-cited order. */
    fun videosFor(lesson: Lesson): List<Pair<String, Video>> =
        lesson.sections.flatMap { it.from }
            .flatMap { entries[it]?.videos.orEmpty() }
            .distinct()
            .mapNotNull { id -> videos[id]?.let { id to it } }
}

data class LearnUnit(val level: String, val name: String, val goal: String, val lessons: List<Lesson>)

data class Lesson(
    val id: String,
    val title: String,
    val minutes: Int,
    val hook: String,
    val sections: List<Section>,
    val tryThis: String,
    val headsUp: String,
    val check: List<Check>,
)

data class Section(val heading: String, val text: String, val from: List<String>)
data class Check(val q: String, val a: String)

/** One merged consensus entry: the "Read more" behind a section. */
data class Entry(
    val action: String,
    val why: String,
    val people: List<String>,
    val agreement: Int,
    val videos: List<String>,
)

data class Video(val title: String, val channel: String) {
    fun url(id: String) = "https://www.youtube.com/watch?v=$id"
}

object LearnContent {
    @Volatile private var cached: Course? = null

    fun load(context: Context): Course = cached ?: synchronized(this) {
        cached ?: parse(
            context.assets.open("learn/deer.json").bufferedReader().use { it.readText() },
        ).also { cached = it }
    }

    internal fun parse(json: String): Course {
        val root = JSONObject(json)
        val units = root.getJSONArray("units").objects().map { u ->
            LearnUnit(
                level = u.getString("level"),
                name = u.getString("unit"),
                goal = u.optString("goal"),
                lessons = u.getJSONArray("lessons").objects().map { l ->
                    Lesson(
                        id = l.getString("id"),
                        title = l.getString("title"),
                        minutes = l.optInt("minutes", 5),
                        hook = l.optString("hook"),
                        sections = l.getJSONArray("sections").objects().map { s ->
                            Section(s.getString("heading"), s.getString("text"), s.getJSONArray("from").strings())
                        },
                        tryThis = l.optString("tryThis"),
                        headsUp = l.optString("headsUp"),
                        check = l.getJSONArray("check").objects().map { Check(it.getString("q"), it.getString("a")) },
                    )
                },
            )
        }
        val entriesJson = root.getJSONObject("entries")
        val entries = entriesJson.keys().asSequence().associateWith { id ->
            val e = entriesJson.getJSONObject(id)
            Entry(
                action = e.optString("action"),
                why = e.optString("why"),
                people = e.getJSONArray("people").strings(),
                agreement = e.optInt("agreement", 1),
                videos = e.getJSONArray("videos").strings(),
            )
        }
        val videosJson = root.getJSONObject("videos")
        val videos = videosJson.keys().asSequence().associateWith { id ->
            val v = videosJson.getJSONObject(id)
            Video(v.getString("title"), v.optString("channel"))
        }
        return Course(units, entries, videos)
    }

    private fun JSONArray.objects(): List<JSONObject> = (0 until length()).map { getJSONObject(it) }
    private fun JSONArray.strings(): List<String> = (0 until length()).map { getString(it) }
}

/**
 * Which lessons the user has checked off, observable by Compose and saved to its own
 * prefs file. Lesson ids are "<unit-slug>-<n>", so reordering lessons inside a unit
 * would shift check-offs; append new lessons at the end of a unit to keep them stable.
 */
object LearnProgress {
    private const val PREFS = "kairos_learn"
    private const val KEY_DONE = "done"

    var done by mutableStateOf<Set<String>>(emptySet())
        private set
    private var loaded = false

    fun ensureLoaded(context: Context) {
        if (loaded) return
        done = prefs(context).getStringSet(KEY_DONE, emptySet()).orEmpty().toSet()
        loaded = true
    }

    fun setDone(context: Context, lessonId: String, isDone: Boolean) {
        ensureLoaded(context)
        done = if (isDone) done + lessonId else done - lessonId
        prefs(context).edit().putStringSet(KEY_DONE, done).apply()
    }

    private fun prefs(context: Context) = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
}
